from wordfreq import word_counts


def test_counts_words():
    assert word_counts("a b a") == {"a": 2, "b": 1}


def test_empty_text():
    assert word_counts("") == {}


def test_ignores_case_and_punctuation():
    assert word_counts("The cat. the CAT, the dog!") == {"the": 3, "cat": 2, "dog": 1}


def test_inner_apostrophe_kept():
    assert word_counts("Don't don't, 'quoted'") == {"don't": 2, "quoted": 1}


def test_punctuation_only_ignored():
    assert word_counts("a ... , a") == {"a": 2}

